#include <iostream>
#include <string>
#include <algorithm>
#include <vector>

int maxLength(const std::string& s) {
    std::string t = "";
    bool f = false;
    for (size_t i = 0; i < s.length(); ++i) {
        char ch = s[i];
        if (ch == '(')
            f = true;
        else if (ch == ')') {
            f = false;
            t += "_";
        }
        if (!f && ch != ')')
            t += ch;
    }
    size_t max_len = 0;
    size_t start = 0;
    for (size_t i = 0; i <= t.length(); ++i) {
        if (i == t.length() || t[i] == '_') {
            size_t length = i - start;
            max_len = std::max(max_len, length);
            start = i + 1;
        }
    }
    return static_cast<int>(max_len);
}

int count(const std::string& s) {
    int m = 0;
    size_t start = 0;
    for (size_t i = 0; i <= s.length(); ++i) {
        if (i == s.length() || s[i] == '_') {
            if (i - start != 0)
                m++;
            start = i + 1;
        }
    }
    return m;
}

int words(const std::string& s) {
    int c = 0;
    std::string t = "";
    bool f = false;
    for (size_t i = 0; i < s.length(); ++i) {
        char ch = s[i];
        if (ch == '(')
            f = true;
        else if (ch == ')') {
            f = false;
            c += count(t);
            t = "";
        }
        if (f && ch != '(')
            t += ch;
    }
    return c;
}

int main() {
    int n;
    std::cin >> n;
    std::string s;
